// # Arguments
//
// * `client` - the endpoint.
// * `topic` - the resource path, as null-terminated UTF-8.
// * `payload` - the bytes to send.
// * `payload_len` - the length of `payload`.
//
// # Returns
//
// [`PamojaStatus::Ok`] once the request has gone out.
//
// # Safety
//
// `client` must be a live handle, `topic` a valid null-terminated UTF-8
// string, and `payload` must point to at least `payload_len` readable bytes or
// be null when that length is 0.
PamojaStatus pamoja_coap_client_send(PamojaCoapClient *client,
                                     const char *topic,
                                     const uint8_t *payload,
                                     uintptr_t payload_len);

// Observes a resource path, so messages published to it arrive at
// [`pamoja_coap_client_recv`].
//
// # Arguments
//
// * `client` - the endpoint.
// * `topic` - the resource path, as null-terminated UTF-8.
//
// # Returns
//
// [`PamojaStatus::Ok`] once observing.
//
// # Safety
//
// `client` must be a live handle and `topic` a valid null-terminated UTF-8
// string.
PamojaStatus pamoja_coap_client_subscribe(PamojaCoapClient *client, const char *topic);

// Waits for the next message on an observed path.
//
// # Arguments
//
// * `client` - the endpoint.
// * `out_message` - receives a message handle, or null when the endpoint is
//   closed.
//
// # Returns
//
// [`PamojaStatus::Ok`] on success. A null `out_message` with an `Ok` status
// means the endpoint closed rather than that anything failed.
//
// # Safety
//
// `client` must be a live handle and `out_message` must be writable.
PamojaStatus pamoja_coap_client_recv(PamojaCoapClient *client, PamojaMessage **out_message);

// Reports whether the endpoint is bound.
//
// # Arguments
//
// * `client` - the endpoint.
//
// # Returns
//
// `true` when bound, or `false` if `client` is null.
//
// # Safety
//
// `client` must be a live handle from [`pamoja_coap_client_new`], or null.
bool pamoja_coap_client_is_connected(PamojaCoapClient *client);

// Releases the socket the endpoint holds.
//
// # Arguments
//
// * `client` - the endpoint.
//
// # Returns
//
// [`PamojaStatus::Ok`] once closed.
//
// # Safety
//
// `client` must be a live handle from [`pamoja_coap_client_new`].
PamojaStatus pamoja_coap_client_disconnect(PamojaCoapClient *client);

// Releases a CoAP endpoint handle.
//
// Passing null is a no-op.
//
// # Safety
//
// `client` must be a handle from [`pamoja_coap_client_new`] that has not
// already been freed, or null. After this call it must not be used again.
void pamoja_coap_client_free(PamojaCoapClient *client);

// Creates a CoAP transport for composing into a ladder or a wrapper.
//
// # Arguments
//
// * `config` - the endpoint settings.
//
// # Returns
//
// A handle the caller must release with
// [`pamoja_transport_free`](crate::transport::pamoja_transport_free) or hand to
// a call that consumes it, or null on failure.
//
// # Safety
//
// `config` must point to a valid [`PamojaCoapConfig`] whose strings are valid
// null-terminated UTF-8 for the duration of the call.
PamojaTransport *pamoja_transport_coap(const PamojaCoapConfig *config);

// Converts a JSON document into its CBOR encoding.
//
// # Returns
//
// [`PamojaStatus::Ok`] on success, with `*out_buffer` set to a new buffer handle
// the caller must release with
// [`pamoja_buffer_free`](crate::pamoja_buffer_free), or an error status whose
// message is available from
// [`pamoja_last_error_message`](crate::pamoja_last_error_message).
//
// # Safety
//
// `json` must point to at least `json_len` readable bytes, or be null when
// `json_len` is 0, and `out_buffer` must point to a writable
// `*mut PamojaBuffer`.
PamojaStatus pamoja_codec_json_to_cbor(const uint8_t *json,
                                       uintptr_t json_len,
                                       PamojaBuffer **out_buffer);

// Converts a CBOR document into its JSON encoding.
//
// # Returns
//
// [`PamojaStatus::Ok`] on success, with `*out_buffer` set to a new buffer handle
// the caller must release with
// [`pamoja_buffer_free`](crate::pamoja_buffer_free), or an error status.
//
// # Safety
//
// `cbor` must point to at least `cbor_len` readable bytes, or be null when
// `cbor_len` is 0, and `out_buffer` must point to a writable
// `*mut PamojaBuffer`.
PamojaStatus pamoja_codec_cbor_to_json(const uint8_t *cbor,
                                       uintptr_t cbor_len,
                                       PamojaBuffer **out_buffer);

// Delta-encodes a series of integer samples into a compact buffer.
//
// # Returns
//
// [`PamojaStatus::Ok`] on success, with `*out_buffer` set to a new buffer handle
// the caller must release with
// [`pamoja_buffer_free`](crate::pamoja_buffer_free).
//
// # Safety
//
// `samples` must point to at least `count` readable `int64` values, or be null
// when `count` is 0, and `out_buffer` must point to a writable
// `*mut PamojaBuffer`.
PamojaStatus pamoja_codec_encode_deltas(const int64_t *samples,
                                        uintptr_t count,
                                        PamojaBuffer **out_buffer);

// Decodes a delta-encoded buffer back into its integer samples.
//
// # Returns
//
// [`PamojaStatus::Ok`] on success, with `*out_samples` set to a new handle the
// caller must release with [`pamoja_samples_free`], or
// [`PamojaStatus::Codec`] if the buffer is malformed.
//
// # Safety
//
// `bytes` must point to at least `bytes_len` readable bytes, or be null when
// `bytes_len` is 0, and `out_samples` must point to a writable
// `*mut PamojaSamples`.
PamojaStatus pamoja_codec_decode_deltas(const uint8_t *bytes,
                                        uintptr_t bytes_len,
                                        PamojaSamples **out_samples);

// Quantizes and delta-encodes a batch of float readings.
//
// # Returns
//
// [`PamojaStatus::Ok`] on success, with `*out_buffer` set to a new buffer handle
// the caller must release with
// [`pamoja_buffer_free`](crate::pamoja_buffer_free), or
// [`PamojaStatus::InvalidArgument`] if `scale` is not positive and finite.
//
// # Safety
//
// `readings` must point to at least `count` readable `float` values, or be null
// when `count` is 0, and `out_buffer` must point to a writable
// `*mut PamojaBuffer`.
PamojaStatus pamoja_codec_quantizer_encode(float scale,
                                           const float *readings,
                                           uintptr_t count,
                                           PamojaBuffer **out_buffer);

// Decodes a quantized batch back into float readings.
//
// The readings come back to within the precision `scale` selected, which must be
// the same scale the batch was encoded with.
//
// # Returns
//
// [`PamojaStatus::Ok`] on success, with `*out_readings` set to a new handle the
// caller must release with [`pamoja_readings_free`], or
// [`PamojaStatus::Codec`] if the buffer is malformed.
//
// # Safety
//
// `bytes` must point to at least `bytes_len` readable bytes, or be null when
// `bytes_len` is 0, and `out_readings` must point to a writable
// `*mut PamojaReadings`.
PamojaStatus pamoja_codec_quantizer_decode(float scale,
                                           const uint8_t *bytes,
                                           uintptr_t bytes_len,
                                           PamojaReadings **out_readings);

// Returns a pointer to a decoded series of integer samples.
//
// Use [`pamoja_samples_len`] for the count. The pointer is valid until the
// handle is freed.
//
// # Returns
//
// A pointer to the samples, or null if `samples` is null.
//
// # Safety
//
// `samples` must be a live handle from [`pamoja_codec_decode_deltas`], or null.
const int64_t *pamoja_samples_data(const PamojaSamples *samples);

// Returns the number of integer samples in a decoded series.
//
// # Returns
//
// The count, or 0 if `samples` is null.
//
// # Safety
//
// `samples` must be a live handle from [`pamoja_codec_decode_deltas`], or null.
uintptr_t pamoja_samples_len(const PamojaSamples *samples);

// Releases a decoded sample series.
//
// Passing null is a no-op.
//
// # Safety
//
// `samples` must be a handle from [`pamoja_codec_decode_deltas`] that has not
// already been freed, or null. After this call it must not be used again.
void pamoja_samples_free(PamojaSamples *samples);

// Returns a pointer to a decoded series of float readings.
//
// Use [`pamoja_readings_len`] for the count. The pointer is valid until the
// handle is freed.
//
// # Returns
//
// A pointer to the readings, or null if `readings` is null.
//
// # Safety
//
// `readings` must be a live handle from [`pamoja_codec_quantizer_decode`], or
// null.
const float *pamoja_readings_data(const PamojaReadings *readings);

// Returns the number of float readings in a decoded series.
//
// # Returns
//
// The count, or 0 if `readings` is null.
//
// # Safety
//
// `readings` must be a live handle from [`pamoja_codec_quantizer_decode`], or
// null.
uintptr_t pamoja_readings_len(const PamojaReadings *readings);

// Releases a decoded reading series.
//
// Passing null is a no-op.
//
// # Safety
//
// `readings` must be a handle from [`pamoja_codec_quantizer_decode`] that has
// not already been freed, or null. After this call it must not be used again.
void pamoja_readings_free(PamojaReadings *readings);

// Validates a 7-bit I2C address.
//
// The whole `0x00..=0x7F` range is accepted, reserved addresses included, since
// those are still legal on the wire. Test for them with
// [`pamoja_i2c_address_is_reserved`].
//
// # Returns
//
// [`PamojaStatus::Ok`] on success, with `*out_address` set, or
// [`PamojaStatus::InvalidArgument`] if `address` is above `0x7F`.
//
// # Safety
//
// `out_address` must point to a writable `PamojaI2cAddress`.
PamojaStatus pamoja_i2c_address_seven_bit(uint8_t address, PamojaI2cAddress *out_address);

// Validates a 10-bit I2C address.
//
// # Returns
//
// [`PamojaStatus::Ok`] on success, with `*out_address` set, or
// [`PamojaStatus::InvalidArgument`] if `address` is above `0x3FF`.
//
// # Safety
//
// `out_address` must point to a writable `PamojaI2cAddress`.
PamojaStatus pamoja_i2c_address_ten_bit(uint16_t address, PamojaI2cAddress *out_address);

// Returns how many bytes an address frame occupies.
//
// # Returns
//
// `1` for a 7-bit address, `2` for a 10-bit one.
uintptr_t pamoja_i2c_address_frame_len(PamojaI2cAddress address);

// Writes the address bytes a controller puts on the bus for a transfer.
//
// # Returns
//
// [`PamojaStatus::Ok`] on success, with `*out_len` set to how many bytes of
// `out_frame` were written, or [`PamojaStatus::InvalidArgument`] if the address
// is not one this SDK produced or `out_frame_cap` is smaller than
// [`pamoja_i2c_address_frame_len`].
//
// # Safety
//
// `out_frame` must point to at least `out_frame_cap` writable bytes, and
// `out_len` must point to a writable `size_t`.
PamojaStatus pamoja_i2c_address_frame(PamojaI2cAddress address,
                                      PamojaI2cDirection direction,
                                      uint8_t *out_frame,
                                      uintptr_t out_frame_cap,
                                      uintptr_t *out_len);

// Reports whether a 7-bit address falls in a range the I2C specification reserves.
//
// # Returns
//
// `true` for a 7-bit address in `0x00..=0x07` or `0x78..=0x7F`, which leaves
// `0x08..=0x77` for ordinary devices. A 10-bit address is never reserved in this
// sense.
bool pamoja_i2c_address_is_reserved(PamojaI2cAddress address);

// Reports whether an address is the general call address `0x00`.
//
// # Returns
//
// `true` for the broadcast every device on the bus listens to.
bool pamoja_i2c_address_is_general_call(PamojaI2cAddress address);

// Returns the `(CPOL, CPHA)` pair an SPI mode number names.
//
// # Returns
//
// [`PamojaStatus::Ok`] on success, with `*out_cpol` set to whether the clock
// idles high and `*out_cpha` to whether data is sampled on the trailing edge, or
// [`PamojaStatus::InvalidArgument`] if `mode` is above 3.
//
// # Safety
//
// `out_cpol` and `out_cpha` must each point to a writable `bool`.
PamojaStatus pamoja_spi_mode_cpol_cpha(uint8_t mode, bool *out_cpol, bool *out_cpha);

// Returns the SPI mode number a `(CPOL, CPHA)` pair names.
//
// # Returns
//
// The mode number `0..=3`. Every pair names a mode, so this never fails.
uint8_t pamoja_spi_mode_from_cpol_cpha(bool cpol, bool cpha);

// Returns the level a boolean names.
//
// # Returns
//
// [`PamojaPinLevel::High`] for `true`, [`PamojaPinLevel::Low`] for `false`.
PamojaPinLevel pamoja_pin_level_from_bool(bool high);

// Returns the opposite level.
//
// # Returns
//
// The inverted level.
PamojaPinLevel pamoja_pin_level_inverted(PamojaPinLevel level);

// Reports whether a change from one level to another fires an interrupt trigger.
//
// # Returns
//
// `true` if the transition matches `edge`; `false` for the other direction or
// for no change at all.
bool pamoja_pin_edge_triggered_by(PamojaPinEdge edge, PamojaPinLevel from, PamojaPinLevel to);

// Returns the physical level that represents a logical state under a polarity.
//
// # Returns
//
// The level to drive, which for active-low wiring is the inverse of `asserted`.
PamojaPinLevel pamoja_pin_polarity_level(PamojaPinPolarity polarity, bool asserted);

// Reports whether a physical level means the signal is asserted.
//
// # Returns
//
// `true` if `level` asserts the signal under `polarity`.
bool pamoja_pin_polarity_is_asserted(PamojaPinPolarity polarity, PamojaPinLevel level);

