//
// # Returns
//
// The checksum, or 0 if `data` is null with a non-zero length.
//
// # Safety
//
// `data` must point to at least `data_len` readable bytes when that length is
// non-zero.
uint16_t pamoja_mesh_crc16(const uint8_t *data, uintptr_t data_len);

