// `out_public_key` must point to at least [`PAMOJA_SESSION_KEY_LEN`] writable
// bytes.
PamojaStatus pamoja_agreement_key_public(const PamojaAgreementKey *key, uint8_t *out_public_key);

// Releases an agreement key handle.
//
// Passing null is a no-op.
//
// # Safety
//
// `key` must be a handle from [`pamoja_agreement_key_from_seed`] that has not
// already been freed, or null. After this call it must not be used again.
void pamoja_agreement_key_free(PamojaAgreementKey *key);

// Establishes a session with a peer.
//
// Both devices call this with the same salt and opposite roles, and arrive at
// the same key without either sending it. The salt is a fresh per-session value
// exchanged in the clear; reusing one with the same pair of keys reuses the
// session key, so it must change each session.
//
// # Arguments
//
// * `local` - this device key-agreement secret.
// * `peer_public_key` - the [`PAMOJA_SESSION_KEY_LEN`]-byte public key of the
//   peer, already authenticated by pinning or by a signature.
// * `salt` - the fresh per-session salt both sides share.
// * `salt_len` - the length of `salt`.
// * `role` - whether this device opens the session or answers.
//
// # Returns
//
// A handle the caller must release with [`pamoja_session_free`], or null on
// failure.
//
// # Safety
//
// `local` must be a live agreement key handle, `peer_public_key` must point to
// at least [`PAMOJA_SESSION_KEY_LEN`] readable bytes, and `salt` must point to
// at least `salt_len` readable bytes, or be null when `salt_len` is 0.
PamojaSession *pamoja_session_establish(const PamojaAgreementKey *local,
                                        const uint8_t *peer_public_key,
                                        const uint8_t *salt,
                                        uintptr_t salt_len,
                                        PamojaSessionRole role);

// Seals a message for the peer, encrypting it in place.
//
// The associated data is authenticated but not encrypted, so it stays readable
// on the wire yet cannot be altered: a device identifier or a routing header
// belongs there. On success `buf` holds the ciphertext and `out_sealed` holds
// the counter and tag to send with it.
//
// # Arguments
//
// * `session` - the session.
// * `buf` - the plaintext, replaced by the ciphertext of equal length.
// * `len` - the length of `buf`.
// * `aad` - associated data to authenticate alongside the message.
// * `aad_len` - the length of `aad`.
// * `out_sealed` - receives the counter and tag.
//
// # Returns
//
// [`PamojaStatus::Ok`] on success.
//
// # Safety
//
// `session` must be a live handle from [`pamoja_session_establish`], `buf` must
// point to at least `len` readable and writable bytes or be null when `len` is
// 0, `aad` must point to at least `aad_len` readable bytes or be null when
// `aad_len` is 0, and `out_sealed` must be writable.
PamojaStatus pamoja_session_seal(PamojaSession *session,
                                 uint8_t *buf,
                                 uintptr_t len,
                                 const uint8_t *aad,
                                 uintptr_t aad_len,
                                 PamojaSealed *out_sealed);

// Opens a message from the peer, verifying it and decrypting it in place.
//
// A message is rejected if its counter repeats or is older than the replay
// window still tracks, and if its tag does not authenticate. On any rejection
// `buf` is left zeroed, so a failed open never yields readable bytes.
//
// # Arguments
//
// * `session` - the session.
// * `sealed` - the counter and tag that arrived with the ciphertext.
// * `buf` - the ciphertext, replaced by the plaintext on success.
// * `len` - the length of `buf`.
// * `aad` - the same associated data the sender authenticated.
// * `aad_len` - the length of `aad`.
//
// # Returns
//
// [`PamojaStatus::Ok`] if the message is authentic and fresh, or
// [`PamojaStatus::Auth`] if it is not, with the message from
// [`pamoja_last_error_message`](crate::pamoja_last_error_message) saying whether
// it failed authentication or repeated a counter.
//
// # Safety
//
// `session` must be a live handle from [`pamoja_session_establish`], `buf` must
// point to at least `len` readable and writable bytes or be null when `len` is
// 0, and `aad` must point to at least `aad_len` readable bytes or be null when
// `aad_len` is 0.
PamojaStatus pamoja_session_open(PamojaSession *session,
                                 PamojaSealed sealed,
                                 uint8_t *buf,
                                 uintptr_t len,
                                 const uint8_t *aad,
                                 uintptr_t aad_len);

// Releases a session handle.
//
// Passing null is a no-op.
//
// # Safety
//
// `session` must be a handle from [`pamoja_session_establish`] that has not
// already been freed, or null. After this call it must not be used again.
void pamoja_session_free(PamojaSession *session);

// Computes a keyed hash over a message.
//
// This is the primitive a host uses to authenticate a pairing exchange or a
// single command, where a whole session would be more than the job needs.
//
// # Arguments
//
// * `key` - the secret key.
// * `key_len` - the length of `key`.
// * `message` - the message to authenticate.
// * `message_len` - the length of `message`.
// * `out_digest` - receives [`PAMOJA_SESSION_KEY_LEN`] bytes.
//
// # Returns
//
// [`PamojaStatus::Ok`] on success.
//
// # Safety
//
// `key` and `message` must point to at least their stated lengths of readable
// bytes, or be null when those lengths are 0, and `out_digest` must point to at
// least [`PAMOJA_SESSION_KEY_LEN`] writable bytes.
PamojaStatus pamoja_session_hmac_sha256(const uint8_t *key,
                                        uintptr_t key_len,
                                        const uint8_t *message,
                                        uintptr_t message_len,
                                        uint8_t *out_digest);

// Expands input keying material into as many bytes as are asked for.
//
// # Arguments
//
// * `salt` - the salt, which may be empty.
// * `salt_len` - the length of `salt`.
// * `ikm` - the input keying material.
// * `ikm_len` - the length of `ikm`.
// * `info` - context binding the output to its purpose, which may be empty.
// * `info_len` - the length of `info`.
// * `out` - receives `out_len` derived bytes.
// * `out_len` - how many bytes to derive.
//
// # Returns
//
// [`PamojaStatus::Ok`] on success.
//
// # Safety
//
// `salt`, `ikm`, and `info` must each point to at least their stated lengths of
// readable bytes, or be null when those lengths are 0, and `out` must point to
// at least `out_len` writable bytes, or be null when `out_len` is 0.
PamojaStatus pamoja_session_hkdf_sha256(const uint8_t *salt,
                                        uintptr_t salt_len,
                                        const uint8_t *ikm,
                                        uintptr_t ikm_len,
                                        const uint8_t *info,
                                        uintptr_t info_len,
                                        uint8_t *out,
                                        uintptr_t out_len);

// Creates a sensor that reads around a baseline.
//
// # Arguments
//
// * `baseline` - the value it reads before drift and noise.
// * `drift_per_read` - how much the baseline moves each read, or 0 for none.
// * `noise` - the amplitude of the wobble around it, or 0 for none.
// * `seed` - the seed for that wobble, so a run repeats.
//
// # Returns
//
// A handle the caller must release with [`pamoja_sim_sensor_free`].
PamojaSimSensor *pamoja_sim_sensor_new(float baseline,
                                       float drift_per_read,
                                       float noise,
                                       uint32_t seed);

// Takes the next reading.
//
// # Arguments
//
// * `sensor` - the sensor.
// * `out_reading` - receives the reading.
//
// # Returns
//
// [`PamojaStatus::Ok`] on success.
//
// # Safety
//
// `sensor` must be a live handle from [`pamoja_sim_sensor_new`] and
// `out_reading` must be writable.
PamojaStatus pamoja_sim_sensor_read(PamojaSimSensor *sensor, float *out_reading);

// Releases a simulated sensor handle.
//
// Passing null is a no-op.
//
// # Safety
//
// `sensor` must be a handle from [`pamoja_sim_sensor_new`] that has not already
// been freed, or null. After this call it must not be used again.
void pamoja_sim_sensor_free(PamojaSimSensor *sensor);

// Creates a sensor that reads back a recorded series.
//
// This is how a caller replays a real capture, so a test asks what the code
// does with readings that actually happened rather than ones it invented.
//
// # Arguments
//
// * `readings` - the series to read back.
// * `count` - how many readings `readings` holds.
// * `repeating` - `true` to start again at the beginning once exhausted,
//   `false` to keep returning the last one.
//
// # Returns
//
// A handle the caller must release with [`pamoja_replay_free`].
//
// # Safety
//
// `readings` must point to at least `count` readable floats, or be null when
// `count` is 0.
PamojaReplay *pamoja_replay_new(const float *readings, uintptr_t count, bool repeating);

// Takes the next reading from a replay.
//
// # Arguments
//
// * `replay` - the replay.
// * `out_reading` - receives the reading.
//
// # Returns
//
// [`PamojaStatus::Ok`] on success.
//
// # Safety
//
// `replay` must be a live handle from [`pamoja_replay_new`] and `out_reading`
// must be writable.
PamojaStatus pamoja_replay_read(PamojaReplay *replay, float *out_reading);

// Releases a replay handle.
//
// Passing null is a no-op.
//
// # Safety
//
// `replay` must be a handle from [`pamoja_replay_new`] that has not already
// been freed, or null. After this call it must not be used again.
void pamoja_replay_free(PamojaReplay *replay);

// Creates an actuator that records every command instead of acting on one.
//
// # Returns
//
// A handle the caller must release with [`pamoja_recording_actuator_free`].
PamojaRecordingActuator *pamoja_recording_actuator_new(void);

// Applies a command, which the actuator records rather than acts on.
//
// # Arguments
//
// * `actuator` - the actuator.
// * `command` - the value commanded.
//
// # Returns
//
// [`PamojaStatus::Ok`] on success.
//
// # Safety
//
// `actuator` must be a live handle from [`pamoja_recording_actuator_new`].
PamojaStatus pamoja_recording_actuator_apply(PamojaRecordingActuator *actuator, float command);

// Reports how many commands an actuator has been given.
//
// # Arguments
//
// * `actuator` - the actuator.
//
// # Returns
//
// The number of commands, or 0 if `actuator` is null.
//
// # Safety
//
// `actuator` must be a live handle from [`pamoja_recording_actuator_new`], or
// null.
uintptr_t pamoja_recording_actuator_len(const PamojaRecordingActuator *actuator);

// Copies out the commands an actuator recorded, oldest first.
//
// # Arguments
//
// * `actuator` - the actuator.
// * `out_commands` - receives up to `capacity` commands.
// * `capacity` - how many floats `out_commands` can hold.
//
// # Returns
//
// How many commands were written, which is the smaller of `capacity` and the
// count from [`pamoja_recording_actuator_len`].
//
// # Safety
//
// `actuator` must be a live handle, and `out_commands` must point to at least
// `capacity` writable floats or be null when `capacity` is 0.
uintptr_t pamoja_recording_actuator_commands(const PamojaRecordingActuator *actuator,
                                             float *out_commands,
                                             uintptr_t capacity);

// Releases a recording actuator handle.
//
// Passing null is a no-op.
//
// # Safety
//
// `actuator` must be a handle from [`pamoja_recording_actuator_new`] that has
// not already been freed, or null. After this call it must not be used again.
void pamoja_recording_actuator_free(PamojaRecordingActuator *actuator);

// Creates a robot that moves only in arithmetic.
//
// # Arguments
//
// * `start` - the pose it begins at.
// * `dt` - the seconds each command advances it; its magnitude is used.
//
// # Returns
//
// A handle the caller must release with [`pamoja_sim_robot_free`].
PamojaSimRobot *pamoja_sim_robot_new(PamojaPose start, float dt);

// Drives the robot for one time step.
//
// # Arguments
//
// * `robot` - the robot.
// * `command` - the speeds to hold for one step.
//
// # Returns
//
// [`PamojaStatus::Ok`] on success.
//
// # Safety
//
// `robot` must be a live handle from [`pamoja_sim_robot_new`].
PamojaStatus pamoja_sim_robot_apply(PamojaSimRobot *robot, PamojaTwist command);

// Reads where the robot has got to.
//
// # Arguments
//
// * `robot` - the robot.
//
// # Returns
//
// The pose reached so far, or an all-zero pose if `robot` is null.
//
// # Safety
//
// `robot` must be a live handle from [`pamoja_sim_robot_new`], or null.
PamojaPose pamoja_sim_robot_pose(const PamojaSimRobot *robot);

// Releases a simulated robot handle.
//
// Passing null is a no-op.
//
// # Safety
//
// `robot` must be a handle from [`pamoja_sim_robot_new`] that has not already
// been freed, or null. After this call it must not be used again.
void pamoja_sim_robot_free(PamojaSimRobot *robot);

// Creates a buffer held in memory.
//
// # Arguments
//
// * `capacity` - the most records to hold, or 0 for no bound. A full store
//   refuses the next append rather than dropping anything, so a record is
//   never lost without the caller being told.
//
// # Returns
//
// A handle the caller must release with [`pamoja_store_free`] or hand to a call
// that consumes it.
PamojaStore *pamoja_store_memory(uintptr_t capacity);

// Opens a buffer backed by a directory, so it survives a restart.
//
// # Arguments
//
// * `dir` - the directory to hold records in, as null-terminated UTF-8. It is
//   created if it does not exist.
//
// # Returns
//
// A handle the caller must release with [`pamoja_store_free`] or hand to a call
// that consumes it, or null if the directory cannot be opened.
//
// # Safety
//
// `dir` must be a valid null-terminated UTF-8 string for the duration of the
// call.
PamojaStore *pamoja_store_file(const char *dir);

// Adds a record to the end of a buffer.
//
// # Arguments
//
// * `store` - the buffer.
// * `record` - the bytes to hold.
// * `record_len` - the length of `record`.
//
// # Returns
//
// [`PamojaStatus::Ok`] once the record is held.
//
// # Safety
//
// `store` must be a live handle, and `record` must point to at least
// `record_len` readable bytes or be null when that length is 0.
PamojaStatus pamoja_store_append(PamojaStore *store, const uint8_t *record, uintptr_t record_len);

// Reads the oldest record without removing it.
//
// # Arguments
//
// * `store` - the buffer.
// * `out_record` - receives a buffer handle, or null when the store is empty.
//
// # Returns
//
// [`PamojaStatus::Ok`] on success. A null `out_record` with an `Ok` status
// means the buffer is empty.
//
// # Safety
//
// `store` must be a live handle and `out_record` must be writable.
PamojaStatus pamoja_store_peek(PamojaStore *store, PamojaBuffer **out_record);

// Removes and returns the oldest record.
//
// # Arguments
//
// * `store` - the buffer.
// * `out_record` - receives a buffer handle, or null when the store is empty.
//
// # Returns
//
// [`PamojaStatus::Ok`] on success. A null `out_record` with an `Ok` status
// means the buffer is empty.
//
// # Safety
//
// `store` must be a live handle and `out_record` must be writable.
PamojaStatus pamoja_store_pop(PamojaStore *store, PamojaBuffer **out_record);

// Reports how many records a buffer holds.
//
// # Arguments
//
// * `store` - the buffer.
// * `out_len` - receives the count.
//
// # Returns
//
// [`PamojaStatus::Ok`] on success.
//
// # Safety
//
// `store` must be a live handle and `out_len` must be writable.
PamojaStatus pamoja_store_len(PamojaStore *store, uintptr_t *out_len);

// Sends every held record over a transport, oldest first.
//
// A record is removed only once the transport has taken it, so a link that
// fails part-way leaves the rest of the queue intact for the next attempt.
//
// # Arguments
//
// * `store` - the buffer to drain.
// * `transport` - the transport to send over, borrowed rather than consumed.
// * `topic` - the topic to send to, as null-terminated UTF-8.
// * `out_sent` - receives how many records went out, or may be null.
//
// # Returns
//
// [`PamojaStatus::Ok`] if the whole buffer drained, or a transport error with
// `out_sent` holding how many got through before it stopped.
//
// # Safety
//
// `store` and `transport` must be live handles, `topic` a valid
// null-terminated UTF-8 string, and `out_sent` writable or null.
PamojaStatus pamoja_store_drain_to(PamojaStore *store,
                                   PamojaTransport *transport,
                                   const char *topic,
                                   uintptr_t *out_sent);

// Releases a store handle.
//
// Passing null is a no-op.
//
// # Safety
//
// `store` must be a handle from a call that produced one and that has not
// already been freed or consumed, or null. After this call it must not be used
// again.
void pamoja_store_free(PamojaStore *store);

// Returns the level a link cost calls for.
//
// # Arguments
//
// * `cost` - what the link currently costs.
//
// # Returns
//
// The lowest level still worth its bytes at that cost.
PamojaTelemetryLevel pamoja_link_cost_threshold(PamojaLinkCost cost);

// Creates a reporter that ships events at or above a level.
//
// # Arguments
//
// * `threshold` - the lowest level to ship.
//
// # Returns
//
// A handle the caller must release with [`pamoja_reporter_free`].
PamojaReporter *pamoja_reporter_new(PamojaTelemetryLevel threshold);

// Returns the level a reporter is currently shipping from.
//
// # Arguments
//
// * `reporter` - the reporter.
//
// # Returns
//
// The threshold, or [`PamojaTelemetryLevel::Trace`] if `reporter` is null.
//
// # Safety
//
// `reporter` must be a live handle from [`pamoja_reporter_new`], or null.
PamojaTelemetryLevel pamoja_reporter_threshold(const PamojaReporter *reporter);

// Moves the level a reporter ships from.
//
// # Arguments
//
// * `reporter` - the reporter.
// * `threshold` - the new lowest level to ship.
//
// # Safety
//
// `reporter` must be a live handle from [`pamoja_reporter_new`], or null.
void pamoja_reporter_set_threshold(PamojaReporter *reporter, PamojaTelemetryLevel threshold);

// Moves the threshold to match what the link now costs.
//
// # Arguments
//
// * `reporter` - the reporter.
// * `cost` - what the link currently costs.
//
// # Safety
//
// `reporter` must be a live handle from [`pamoja_reporter_new`], or null.
void pamoja_reporter_adapt_to(PamojaReporter *reporter, PamojaLinkCost cost);

// Records an event and reports whether it is worth shipping.
//
// Only the level crosses the boundary, because the level is the whole of what
// the reporter decides on. The code and the optional value stay with the caller,
// which is free to ship its own event when this returns `true`.
//
// # Arguments
//
// * `reporter` - the reporter.
// * `level` - the severity of the event that occurred.
//
// # Returns
//
// `true` if the event passed the threshold and should be shipped, or `false` if
// it was counted and dropped, or `reporter` is null.
//
// # Safety
//
// `reporter` must be a live handle from [`pamoja_reporter_new`], or null.
bool pamoja_reporter_record(PamojaReporter *reporter, PamojaTelemetryLevel level);

// Returns how many events a reporter has seen at a level, shipped or not.
//
// # Arguments
//
// * `reporter` - the reporter.
// * `level` - the level to count.
//
// # Returns
//
// The count, or 0 if `reporter` is null.
//
// # Safety
//
// `reporter` must be a live handle from [`pamoja_reporter_new`], or null.
uint32_t pamoja_reporter_count(const PamojaReporter *reporter, PamojaTelemetryLevel level);

// Returns how many events a reporter has seen across every level.
//
// # Arguments
//
// * `reporter` - the reporter.
//
// # Returns
//
// The total, or 0 if `reporter` is null.
//
// # Safety
//
// `reporter` must be a live handle from [`pamoja_reporter_new`], or null.
uint32_t pamoja_reporter_total(const PamojaReporter *reporter);

// Returns how many events passed the threshold and were shipped.
//
// # Arguments
//
// * `reporter` - the reporter.
//
// # Returns
//
// The emitted count, or 0 if `reporter` is null.
//
// # Safety
//
// `reporter` must be a live handle from [`pamoja_reporter_new`], or null.
uint32_t pamoja_reporter_emitted(const PamojaReporter *reporter);

// Returns how many events the threshold dropped.
//
// # Arguments
//
// * `reporter` - the reporter.
//
// # Returns
//
// The dropped count, or 0 if `reporter` is null.
//
// # Safety
//
// `reporter` must be a live handle from [`pamoja_reporter_new`], or null.
uint32_t pamoja_reporter_dropped(const PamojaReporter *reporter);

// Takes a snapshot of the counters to ship in place of the event stream.
//
// # Arguments
//
// * `reporter` - the reporter.
//
// # Returns
//
// The snapshot, or an all-zero snapshot if `reporter` is null.
//
// # Safety
//
// `reporter` must be a live handle from [`pamoja_reporter_new`], or null.
PamojaTelemetrySnapshot pamoja_reporter_snapshot(const PamojaReporter *reporter);

// Releases a reporter handle.
//
// Passing null is a no-op.
//
// # Safety
//
// `reporter` must be a handle from [`pamoja_reporter_new`] that has not already
// been freed, or null. After this call it must not be used again.
void pamoja_reporter_free(PamojaReporter *reporter);

// Returns the topic a message arrived on.
//
// # Arguments
//
// * `message` - the message.
//
// # Returns
//
// A null-terminated UTF-8 string owned by the message and valid until it is
// freed, or null if `message` is null.
